import json

# Test input 6x6
test_input = [
    [0, 9, 3, 3, 1, 5],
    [7, 5, 3, 3, 1, 7],
    [3, 3, 3, 3, 9, 2],
    [2, 4, 0, 7, 3, 3],
    [4, 3, 5, 3, 3, 3],
    [3, 3, 3, 3, 3, 3]
]

def rotate_cw(grid):
    n = len(grid)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            result[n-1-j][i] = grid[i][j]
    return result

def rotate_ccw(grid):
    n = len(grid)
    result = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            result[i][n-1-j] = grid[j][i]
    return result

def rotate_180(grid):
    return rotate_cw(rotate_cw(grid))

n = 6

# Build output 12x6
output = [[0]*n for _ in range(2*n)]

# TL (rows 0-5, cols 0-5) = original
for r in range(n):
    for c in range(n):
        output[r][c] = test_input[r][c]

# BL (rows 6-11, cols 0-5) = 90° CW of input
rot_cw = rotate_cw(test_input)
for r in range(n):
    for c in range(n):
        output[r+n][c] = rot_cw[r][c]

# TR (rows 0-5, cols 6-11)? Wait, output should be 12x6...
